gdjs.Vs_32Gabs_32_45_32FreeplayCode.userFunc0x463c530 = function GDJSInlineCode(runtimeScene) {
"use strict";
const filesArray = runtimeScene.getVariables().get("WeekFilesList");
filesArray.castTo("array");
filesArray.clearChildren(); 
const recursos = globalThis.gdjs.projectData.resources.resources || [];

recursos.forEach(recurso => {
    const caminho = recurso.name.replace(/\\/g, "/").toLowerCase();
    const isAssetWeek = caminho.match(/^assets\/weeks\/[^\/]+\.json$/);
    const isModWeek = caminho.match(/^mods\/[^\/]+\/weeks\/[^\/]+\.json$/);
    
    if (isAssetWeek || isModWeek) {
        const proximoIndice = filesArray.getChildrenCount();
        filesArray.getChild(proximoIndice.toString()).setString(recurso.name);
    }
});
};
